/**
 * True byte attribution: for each generated byte range in the entry chunk,
 * credit its mapped source. Uses the sourcemap's mappings segment positions.
 */
import { readFileSync } from "node:fs";
import { join, resolve } from "node:path";

const dist = resolve("apps/web/dist");
const html = readFileSync(join(dist, "index.html"), "utf8");
const entry = html.match(/src="\/assets\/(index-[^"]+\.js)"/)?.[1];
const jsBytes = readFileSync(join(dist, "assets", entry));
const map = JSON.parse(
  readFileSync(join(dist, "assets", entry + ".map"), "utf8"),
);

const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
function decodeVlq(str) {
  const out = [];
  let shift = 0,
    value = 0;
  for (const c of str) {
    const digit = B64.indexOf(c);
    if (digit === -1) continue;
    value += (digit & 31) << shift;
    if (digit & 32) {
      shift += 5;
    } else {
      const negate = value & 1;
      value >>= 1;
      out.push(negate ? -value : value);
      value = 0;
      shift = 0;
    }
  }
  return out;
}

// per-source credited bytes
const credit = new Array(map.sources.length).fill(0);
let genLine = 0;
const prev = { genCol: 0, srcIdx: 0, srcLine: 0, srcCol: 0 };
let totalMapped = 0;

for (const line of map.mappings.split(";")) {
  let genCol = 0;
  const segs = [];
  for (const seg of line.split(",")) {
    if (!seg) continue;
    const f = decodeVlq(seg);
    genCol += f[0];
    if (f.length >= 4) {
      prev.srcIdx += f[1];
      prev.srcLine += f[2];
      prev.srcCol += f[3];
      segs.push({ genCol, srcIdx: prev.srcIdx });
    } else {
      segs.push({ genCol, srcIdx: null });
    }
  }
  // find line length in generated file
  const lineStart = jsBytes.indexOf(0x0a, totalMapped);
  const lineEnd = lineStart === -1 ? jsBytes.length : lineStart;
  // walk segments on this line crediting gaps to their source
  for (let i = 0; i < segs.length; i++) {
    const start = totalMapped + segs[i].genCol;
    const nextCol =
      i + 1 < segs.length ? segs[i + 1].genCol : lineEnd - totalMapped;
    const end = totalMapped + Math.min(nextCol, lineEnd - totalMapped);
    if (segs[i].srcIdx !== null && end > start) {
      credit[segs[i].srcIdx] += end - start;
    }
  }
  totalMapped = lineEnd + 1;
  genLine++;
}

console.log(
  `entry ${entry}: ${(jsBytes.length / 1024).toFixed(0)} KB generated\n`,
);
const rows = map.sources
  .map((s, i) => ({ source: s.replace(/^\.\.?\//, ""), bytes: credit[i] }))
  .filter((r) => r.bytes > 0)
  .sort((a, b) => b.bytes - a.bytes);

const covered = rows.reduce((n, r) => n + r.bytes, 0);
console.log(
  `attributed: ${(covered / 1024).toFixed(0)} KB of ${(jsBytes.length / 1024).toFixed(0)} KB\n`,
);
console.log("TOP 25 BY REAL GENERATED BYTES:");
for (const r of rows.slice(0, 25)) {
  console.log(`  ${(r.bytes / 1024).toFixed(1).padStart(8)} KB  ${r.source}`);
}
